<main class="mdq-page"><div class="mdq-wrap"><div class="mdq-page-intro"><div class="mdq-kicker">Pharmacy catalogue</div><h1><?= $search ? 'Search results' : 'Shop medicines'; ?></h1><p><?= $search ? 'Showing results for “'.htmlspecialchars($search).'”.' : 'Genuine products, clear pricing and pharmacist-backed support.'; ?></p></div><div class="mdq-toolbar"><form action="<?= $home; ?>/products" method="get"><input class="mdq-field" name="search" value="<?= htmlspecialchars($search??''); ?>" placeholder="Search medicines, vitamins or care essentials"><button class="mdq-btn mdq-btn-primary" type="submit">Search</button></form><div class="mdq-filters"><a class="mdq-chip <?= empty($category_id)?'active':''; ?>" href="<?= $home; ?>/products">All products</a><?php foreach(($categories??[]) as $cat): ?><a class="mdq-chip <?= (int)($category_id??0)==(int)$cat->id?'active':''; ?>" href="<?= $home; ?>/products?category=<?= (int)$cat->id; ?>"><?= htmlspecialchars($cat->category_name); ?></a><?php endforeach; ?></div></div><?php if(!empty($products)): ?><div class="mdq-products" style="padding-bottom:60px;"><?php foreach($products as $p): $price=$p->effective_price??$p->sales_price;$img=sf_product_image_exists($p->item_image??'')?mdq_products_img($p->item_image):'';$name=htmlspecialchars($p->item_name,ENT_QUOTES);$jsName=htmlspecialchars(json_encode((string)$p->item_name),ENT_QUOTES);$jsImage=htmlspecialchars(json_encode((string)($p->item_image??'')),ENT_QUOTES); ?><article class="mdq-product"><a class="mdq-product-media" href="<?= $home; ?>/product/<?= (int)$p->id; ?>" aria-label="View <?= $name; ?>"><?php if($img): ?><img src="<?= htmlspecialchars($img,ENT_QUOTES); ?>" alt="<?= $name; ?>" loading="lazy"><?php else: ?><span class="mdq-product-placeholder" aria-hidden="true"><?= htmlspecialchars((string)($store->store_name ?? 'Pharmacy')); ?></span><?php endif; ?></a><div class="mdq-product-body"><?php if(!empty($p->category_name)): ?><div class="mdq-product-category"><?= htmlspecialchars($p->category_name); ?></div><?php endif; ?><a class="mdq-product-name" href="<?= $home; ?>/product/<?= (int)$p->id; ?>"><?= $name; ?></a><div class="mdq-product-bottom"><span class="mdq-price"><?= sf_currency($price,$cur); ?></span><button class="mdq-add" type="button" aria-label="Add <?= $name; ?> to cart" onclick="event.preventDefault();event.stopPropagation();addToCart(<?= (int)$p->id; ?>,'product',<?= $jsName; ?>,<?= json_encode((float)$price); ?>,<?= $jsImage; ?>,1,<?= (int)($p->stock??0); ?>)"><svg class="mdq-inline-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2.3 11.2a2 2 0 0 0 2 1.6h7.9a2 2 0 0 0 1.9-1.5L21 8H6"></path><circle cx="10" cy="20" r="1"></circle><circle cx="18" cy="20" r="1"></circle></svg><span>Add to Cart</span></button></div></div></article><?php endforeach; ?></div><?php if(($total_pages??1)>1): ?><div class="mdq-filters" style="justify-content:center;padding:0 0 70px;"><?php for($i=1;$i<=$total_pages;$i++): ?><a class="mdq-chip <?= $i==($page??1)?'active':''; ?>" href="<?= $home; ?>/products?page=<?= $i; ?><?= !empty($category_id)?'&category='.(int)$category_id:''; ?><?= !empty($search)?'&search='.urlencode($search):''; ?>"><?= $i; ?></a><?php endfor; ?></div><?php endif; ?><?php else: ?><div class="mdq-empty"><h2>No medicines found</h2><p>Try another search or browse all products.</p><a class="mdq-btn mdq-btn-primary" href="<?= $home; ?>/products">View all products</a></div><?php endif; ?></div></main>
